"""Whether a settled claim's entry is visible in the ledger right now.

Only the period listing is used (covered by the vendor's base fee). Per-entry
`show` calls are billed per call and stay with the finance reconciliation desk
(EXP-412), so they must not be made from the request path.
"""
from hbexpense.models import POSTED
from hbexpense.util.dates import month_bounds, month_of


class LedgerStatusService:
    def __init__(self, ledger):
        self.ledger = ledger

    def statuses(self, claims):
        """Map claim id -> "booked" / "not_booked" for posted claims, None otherwise.

        One listing call per month covers every posted claim in that month.
        """
        by_month = {}
        for claim in claims:
            if claim.status == POSTED:
                by_month.setdefault(month_of(claim.spent_on), []).append(claim)
        result = {claim.claim_id: None for claim in claims}
        for month, group in by_month.items():
            date_from, date_to = month_bounds(month)
            receipts = {row.receipt for row in self.ledger.list_rows(date_from, date_to)}
            for claim in group:
                result[claim.claim_id] = "booked" if claim.receipt in receipts else "not_booked"
        return result

